        internal void Prepare(GeneratedImage image)
        {
            heading.Select(0);RefreshProviders();if(image==null)return;var p=pet.Settings.ImageProviders.FirstOrDefault(v=>v.Id==image.ProviderId);if(p!=null)providers.SelectedItem=p;prompt.Text=image.Prompt;size.Text=String.IsNullOrEmpty(image.Size)?TextResources.Get("imageWorkspacePage.prepare.sizeStringIsNullOrEmpty"):image.Size;quality.Text=String.IsNullOrEmpty(image.Quality)?TextResources.Get("imageWorkspacePage.prepare.qualityStringIsNullOrEmpty"):image.Quality;
            reference=null;referenceId=null;missingReference=false;referencePreview.Children.Clear();LocalizedUi.Set(notice,"Text",()=>(TextResources.Get("imageWorkspacePage.prepare.notice")));
            if(!String.IsNullOrEmpty(image.ReferenceImageId))try{var original=pet.ImageStore.Get(image.ReferenceImageId);reference=pet.ImageStore.Read(image.ReferenceImageId);referenceId=image.ReferenceImageId;referenceMedia=original.MediaType;int width,height;bool limited;var bitmap=ChatImagePreview.DecodeGeneratedImage(reference,220,out width,out height,out limited);referencePreview.Children.Add(new Image{Source=bitmap,MaxHeight=130,HorizontalAlignment=HorizontalAlignment.Left});}catch(Exception error){if(!(error is IOException||error is UnauthorizedAccessException||error is ArgumentException))throw;reference=null;missingReference=true;LocalizedUi.Set(notice,"Text",()=>(TextResources.Get("imageWorkspacePage.prepare.notice.alternativeA")));}
            RefreshReferenceAvailability();
        }
        internal void RefreshProviders(){string selected=(providers.SelectedItem as ImageGenerationProvider??pet.Settings.SelectedImageProvider())==null?null:(providers.SelectedItem as ImageGenerationProvider??pet.Settings.SelectedImageProvider()).Id;providers.ItemsSource=null;providers.ItemsSource=pet.Settings.ImageProviders;providers.SelectedItem=pet.Settings.ImageProviders.FirstOrDefault(p=>p.Id==selected)??pet.Settings.SelectedImageProvider();RefreshReferenceAvailability();}
        void RefreshReferenceAvailability(){if(upload==null||referenceLabel==null)return;var p=providers.SelectedItem as ImageGenerationProvider;upload.IsEnabled=p!=null&&p.SupportsEdits&&!submitting;removeReference.Visibility=reference!=null||missingReference?Visibility.Visible:Visibility.Collapsed;LocalizedUi.Set(referenceLabel,"Text",()=>(reference!=null?TextResources.Format("imageWorkspacePage.refreshReferenceAvailability.referenceLabelReferenceNull",(reference.Length/1024)):p==null?TextResources.Get("imageWorkspacePage.refreshReferenceAvailability.referenceLabelReferenceNull.alternativeA"):!p.SupportsEdits?TextResources.Get("imageWorkspacePage.refreshReferenceAvailability.referenceLabelReferenceNull.alternativeB"):TextResources.Get("imageWorkspacePage.refreshReferenceAvailability.referenceLabelReferenceNull.alternativeC")));}
        void PickReference(){var picker=LocalizedUi.With(new Microsoft.Win32.OpenFileDialog{Title=TextResources.Get("imageWorkspacePage.pickReference.title"),Filter=TextResources.Get("imageWorkspacePage.pickReference.filter"),Multiselect=false},"Title",()=>(TextResources.Get("imageWorkspacePage.pickReference.title")));if(picker.ShowDialog(Window.GetWindow(this))!=true)return;try{var info=new FileInfo(picker.FileName);if(info.Length>50L*1024*1024)throw new InvalidOperationException(TextResources.Get("imageWorkspacePage.pickReference.text"));byte[] bytes=File.ReadAllBytes(info.FullName);int width,height;bool limited;var bitmap=ChatImagePreview.DecodeGeneratedImage(bytes,220,out width,out height,out limited);reference=bytes;referenceId=null;missingReference=false;referenceMedia=info.Extension.ToLowerInvariant()==".webp"?"image/webp":info.Extension.ToLowerInvariant()==".png"?"image/png":"image/jpeg";referencePreview.Children.Clear();referencePreview.Children.Add(new Image{Source=bitmap,MaxHeight=130,HorizontalAlignment=HorizontalAlignment.Left});RefreshReferenceAvailability();}catch(Exception e){LocalizedUi.Set(notice,"Text",()=>(e is InvalidOperationException?e.Message:TextResources.Get("imageWorkspacePage.pickReference.invalidOperationExceptionEMessage")));}}
        internal async Task GenerateAsync()
        {
            if(disposed||submitting)return;var provider=providers.SelectedItem as ImageGenerationProvider;if(provider==null){LocalizedUi.Set(notice,"Text",()=>(TextResources.Get("imageWorkspacePage.generateAsync.notice")));return;}if(String.IsNullOrWhiteSpace(prompt.Text)){LocalizedUi.Set(notice,"Text",()=>(TextResources.Get("imageWorkspacePage.generateAsync.notice.alternativeA")));return;}if(missingReference){LocalizedUi.Set(notice,"Text",()=>(TextResources.Get("imageWorkspacePage.generateAsync.notice.alternativeB")));return;}if(reference!=null&&!provider.SupportsEdits){LocalizedUi.Set(notice,"Text",()=>(TextResources.Get("imageWorkspacePage.generateAsync.notice.alternativeC")));return;}
            ImageGenerationTaskHandle handle=null;submitting=true;start.IsEnabled=false;RefreshReferenceAvailability();
            try{
                try{handle=await AcceptSubmission(provider);if(!disposed)LocalizedUi.Set(notice,"Text",()=>(TextResources.Get("imageWorkspacePage.generateAsync.notice.alternativeD")));}
                finally{submitting=false;if(!disposed){start.IsEnabled=true;RefreshReferenceAvailability();}}
                // Acceptance owns all request/reference snapshots; this continuation retains only a handle.
                await handle.Completion;if(!disposed&&imageJobId==handle.Id)LocalizedUi.Set(notice,"Text",()=>(TextResources.Get("imageWorkspacePage.generateAsync.notice.alternativeE")));
            }catch(OperationCanceledException){if(!disposed&&(handle==null||imageJobId==handle.Id))LocalizedUi.Set(notice,"Text",()=>(TextResources.Get("imageWorkspacePage.generateAsync.notice.alternativeF")));}catch(Exception e){if(!disposed&&(handle==null||imageJobId==handle.Id))LocalizedUi.Set(notice,"Text",()=>(e is ApiException||e is InvalidOperationException||e is TimeoutException||e is IOException?e.Message:TextResources.Get("imageWorkspacePage.generateAsync.iOExceptionEMessage")));}
        }
        Task<ImageGenerationTaskHandle> AcceptSubmission(ImageGenerationProvider provider)
        {
            var request=new ImageGenerationRequest{Provider=provider.Copy(),Prompt=prompt.Text,Size=ImageGenerationSettings.Optional(size),Quality=ImageGenerationSettings.Optional(quality),ReferenceImageBytes=reference,ReferenceMediaType=referenceMedia,ReferenceImageId=referenceId,SessionId="image-workspace",Persistent=pet.Settings.SaveChatHistory};
            return pet.ImageTasks.EnqueueAsync(new ImageGenerationTaskSubmission(Guid.NewGuid().ToString("N"),request,new ImageTaskOrigin{Source=ImageGenerationSource.Workspace}){BeforeStart=id=>{if(!disposed){imageJobId=id;generated.Children.Clear();generated.Children.Add(CreatePreview(id));}return Task.FromResult(0);}},CancellationToken.None);
        }
        ImageGenerationPendingCard CreatePreview(string id){var card=new ImageGenerationPendingCard(pet.ImageTasks,id,()=>pet.Settings.ImageGenerationMotionEnabled,()=>pet.ImageTasks.CancelAsync(id),asset=>new WorkspaceImagePreview(pet,Window.GetWindow(this),pet.ImageStore.Get(asset),Prepare)){HorizontalAlignment=HorizontalAlignment.Stretch,MaxWidth=Double.PositiveInfinity};foreach(FrameworkElement child in card.Children){child.HorizontalAlignment=HorizontalAlignment.Center;child.VerticalAlignment=VerticalAlignment.Center;}return card;}
