            DateTime? from,to;if(!ParseDate(fromDate.Text,false,out from)||!ParseDate(toDate.Text,true,out to)){LocalizedUi.Set(galleryCount,"Text",()=>(TextResources.Get("imageWorkspacePage.refreshGallery.galleryCount")));galleryStatus.Children.Clear();galleryStatus.Children.Add(Ui.Text(galleryCount.Text,12,Ui.Muted));return;}
